export const ARENA_RANKED_COPY_KEYS = [
  'rankedQuickOffer',
  'switchToQuick',
  'rankedEmpty',
  'rankedEmptyHint',
  'continueSearch',
] as const satisfies readonly (keyof typeof C)[];

export type ArenaCopyKey = keyof typeof C;

export function arenaText(lang: Lang, key: ArenaCopyKey): string {
  const [ru, uk, en, es, ptBR, vi, id, tr, pl] = C[key];
  return triLang(lang, { ru, uk, en, es, 'pt-BR': ptBR, vi, id, tr, pl });
}

/**
 * Человеческое название строки в разборе награды.
 *
 * зачем (2026-08-23): экран печатал служебный идентификатор причины как есть,
 * и игрок видел «base_correct · combo». Соответствие живёт здесь, а не в
 * разметке, чтобы полноту переводов проверял тест, а не глаз.
 */
export function arenaAwardReasonText(lang: Lang, reason: ArenaStarLineReason): string {
  switch (reason) {
    case 'base_correct': return arenaText(lang, 'awardBaseCorrect');
    case 'base_pairs': return arenaText(lang, 'awardBasePairs');
    case 'first': return arenaText(lang, 'awardFirst');
    case 'combo': return arenaText(lang, 'awardCombo');
    case 'timeout': return arenaText(lang, 'timeUp');
    case 'broken': return arenaText(lang, 'taskSkipped');
    case 'wrong': return arenaText(lang, 'wrong');
  }
}

/**
 * Сколько живых игроков ищет сейчас.
 *
 * Сами строки и правило склонения лежат в `searching_copy.ts`: там их видно
 * тесту без запуска приложения. Здесь остаётся только выбор локали.
 */
export function arenaSearchingCountText(lang: Lang, count: number): string {
  const value = arenaSearchingCount(count);
  // Ноль — отдельная фраза, а не «0 игроков»: пустой рейтинг честнее назвать
  // пустым, чем показывать цифру, от которой игрок ждёт соперника.
  if (value === 0) return arenaText(lang, 'rankedEmptyHint');
  const forms = arenaSearchingCountForms(value);
  return triLang(lang, {
    ru: forms.ru, uk: forms.uk, en: forms.en, es: forms.es, 'pt-BR': forms['pt-BR'],
    vi: forms.vi, id: forms.id, tr: forms.tr, pl: forms.pl,
  });
}
